.workbench { container-type: inline-size; display: grid; grid-template-columns: minmax(290px, 1fr) minmax(390px, 1.3fr) 32px minmax(0px, 1fr); min-height: 676px; background: var(--surface); border: 1px solid var(--line); border-radius: 10px; overflow: hidden; box-shadow: rgba(0, 0, 0, 0.008) 0px 3px 18px; transition: grid-template-columns 420ms var(--motion-settle); }
