.react-flow { --xy-background-color: transparent; --xy-node-boxshadow-hover: none; --xy-node-boxshadow-selected: none; --xy-controls-button-background-color: var(--surface); --xy-controls-button-background-color-hover: var(--hover); --xy-controls-button-color: var(--secondary); --xy-controls-button-border-color: var(--line); }
