:root[data-theme="dark"] { --bg: #243850; --surface: #233e57d9; --surface-subtle: #243d5533; --surface-raised: #243d53fa; --hover: #829db82e; --line: #c4dff11f; --line-strong: #9bb9d161; --text: #e8f1f8; --muted: #b4c9da; --secondary: #c5d7e5; --brand: #a9cbdc; --brand-hover: #c3dce9; --brand-soft: #6b93aa40; --on-brand: #142e48; --action-bg: #476075; --action-hover: #506a7e; --action-text: #f4f9fc; --action-border: #819aaf; --action-rim: #ffffff40; --selection-bg: #405a70; --selection-text: #f4f9fc; --selection-border: #9bb3c4; --success: #90d7bb; --warning: #e7bf78; --danger: #ffacb6; --graph-line: #86a7c2; --graph-dot: #b5d2e21a; --graph-visited: #7aabc6; --shadow: 0 8px 28px #081c302e; --glass-rim: #c3e2fb38; --glass-highlight: #d9eeff38; --glass-window: #152d4559; --glass-panel: #203c535e; --glass-conversation: #1a344b94; --glass-node: #2d4c68c9; --glass-popup: #233d54f2; --glass-shadow: inset 0 1px 0 var(--glass-highlight), 0 5px 16px #0a1c3426; }
body { background: var(--bg); color: var(--text); }
.glacier-wallpaper { position: fixed; inset: 0px; z-index: -1; pointer-events: none; background: var(--bg); }
.glacier-wallpaper::before, .glacier-wallpaper::after { content: ""; position: absolute; inset: 0px; }
.glacier-wallpaper::before { background: url("data:image/svg+xml,%3csvg%20xmlns='http://www.w3.org/2000/svg'%20viewBox='0%200%201600%201100'%20preserveAspectRatio='xMidYMid%20slice'%3e%3cdefs%3e%3clinearGradient%20id='ice'%20x2='.8'%20y2='1'%3e%3cstop%20stop-color='%23f5fafb'/%3e%3cstop%20offset='.55'%20stop-color='%23b2d3e5'/%3e%3cstop%20offset='1'%20stop-color='%2376accd'/%3e%3c/linearGradient%3e%3clinearGradient%20id='snow'%20x2='1'%20y2='.2'%3e%3cstop%20stop-color='%23d4e5ed'/%3e%3cstop%20offset='.55'%20stop-color='%23f5fafb'/%3e%3cstop%20offset='1'%20stop-color='%2395c2da'/%3e%3c/linearGradient%3e%3c/defs%3e%3cpath%20d='M-200%201120C110%20130%20650%201130%201140%20420S1650%20150%201850%200V1200Z'%20fill='url(%23ice)'/%3e%3cpath%20d='M-200%201130C260%20500%20720%201220%201220%20700S1680%20470%201850%20430V1300Z'%20fill='url(%23snow)'/%3e%3cpath%20d='M-200%201130C260%20500%20720%201220%201220%20700S1680%20470%201850%20430'%20fill='none'%20stroke='%23f6fcff'%20stroke-width='3'/%3e%3c/svg%3e") center center / cover no-repeat; }
.glacier-wallpaper::after { background: radial-gradient(at 30% 12%, rgba(255, 255, 255, 0.396), transparent 65%); }
[data-theme="dark"] .glacier-wallpaper::before { opacity: 0.24; }
[data-theme="dark"] .glacier-wallpaper::after { background: radial-gradient(at 30% 12%, rgba(141, 189, 228, 0.08), transparent 65%); }
.app-shell { position: relative; isolation: isolate; display: grid; grid-template-columns: 68px minmax(0px, 1fr); grid-template-rows: auto 1fr; width: calc(100% - 64px); max-width: 1800px; min-height: 0px; margin: 32px auto; border: 1px solid var(--glass-rim); border-radius: 30px; background: var(--glass-window); box-shadow: inset 0 1px 0 var(--glass-highlight),
    0 30px 80px #254b6626; }
.app-shell::before { content: ""; position: absolute; inset: 0px; z-index: -1; border-radius: inherit; pointer-events: none; backdrop-filter: blur(var(--glass-blur)) saturate(1.2); }
.topbar { grid-column: 1 / -1; height: 72px; padding: 0px 28px; border-radius: 30px 30px 0px 0px; background: rgba(255, 255, 255, 0.04); }
.brand-home { display: flex; align-items: center; gap: 10px; text-decoration: none; color: var(--text); font-size: 21px; font-weight: 650; }
.brand-mark, .brand-mark.small { display: inline-grid; place-items: center; width: 34px; height: 34px; border-radius: 11px; transform: none; color: var(--brand); border: 1px solid var(--glass-rim); background: var(--surface-subtle); box-shadow: var(--glass-shadow); }
.brand-mark.small { width: 24px; height: 24px; border-radius: 8px; }
.wordmark-divider { background: transparent; margin-inline: 15px; }
.topbar-actions { display: flex; align-items: center; gap: 12px; }
.topbar-note { border: 1px solid var(--glass-rim); border-radius: 24px; background: var(--surface-subtle); padding: 8px 13px; font-size: 11px; letter-spacing: 0px; }
.rail { top: 20px; width: 68px; height: calc(-140px + 100dvh); max-height: 100%; align-self: start; background: transparent; border-radius: 0px 0px 0px 30px; }
.rail-top { padding-top: 24px; }
.rail .button-icon { width: 42px; height: 42px; border-radius: 15px; }
.rail .rail-active { background: var(--surface); border-color: var(--glass-rim); box-shadow: var(--glass-shadow); }
.rail-avatar { background: var(--surface-subtle); border-color: var(--glass-rim); }
main { padding: 24px 24px 0px; }
.page-heading { margin-bottom: 24px; }
.page-heading h1 { font-size: 29px; font-weight: 600; letter-spacing: -1px; }
.page-heading > div > .section-kicker { display: block; font-size: 11px; letter-spacing: 0.04em; }
.page-heading p { margin-top: 5px; }
.workbench { overflow: visible; background: transparent; border: 0px; border-radius: 0px; box-shadow: none; }
.conversation-pane, .execution-pane, .inspector-slot { border: 1px solid var(--glass-rim); border-radius: 23px; background: var(--glass-panel); box-shadow: var(--glass-shadow); overflow: clip; }
.conversation-pane { margin-right: 16px; background: var(--glass-conversation); }
.inspector-slot { border: 0px; box-shadow: inset 0 0 0 1px var(--glass-rim),
    var(--glass-shadow); }
.inspector-desktop { background: transparent; }
.inspector-rail { border: 0px; background: transparent; }
.inspector-rail .inspector-toggle { border: 1px solid var(--glass-rim); background: var(--surface); border-radius: 20px; box-shadow: var(--glass-shadow); }
.input-wrap { border-color: var(--glass-rim); border-radius: 19px; background: var(--surface-subtle); box-shadow: inset 0 1px 0 var(--glass-highlight); padding: 13px; }
.model-control .select-trigger { min-width: 0px; max-width: 175px; height: 30px; padding: 0px 6px; color: var(--secondary); background: transparent; border-color: transparent; box-shadow: none; }
.model-control .select-trigger:hover, .model-control .select-trigger[data-state="open"] { color: var(--text); background: var(--surface); }
.model-control .select-trigger > span:first-child { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.button, .select-trigger { border-radius: 22px; }
.button-outline, .select-trigger { border-color: var(--glass-rim); box-shadow: inset 0 1px 0 var(--glass-highlight); }
.button-primary { background: linear-gradient(180deg, #ffffff0a, transparent), var(--action-bg); color: var(--action-text); border-color: var(--action-border); box-shadow: inset 0 1px 0 var(--action-rim),
    0 3px 8px #18374b14; }
.button-primary:hover:not(:disabled) { background: linear-gradient(180deg, #ffffff0a, transparent), var(--action-hover); }
.current-action { border: 1px solid var(--line); border-radius: 12px; background: var(--surface-subtle); }
.current-action.is-running { border-color: var(--brand); }
.flow-node { background: var(--glass-node); border-color: var(--glass-rim); border-radius: 21px; box-shadow: var(--glass-shadow); }
.flow-node::after { border-radius: 25px; }
.node-icon { background: transparent; border-color: transparent; color: var(--brand); }
.node-meta { justify-content: center; }
.react-flow__controls { border-color: var(--glass-rim); border-radius: 12px; }
.timeline-heading { border-top: 1px solid var(--line); }
.timeline-row, .select-item { border-radius: 10px; }
.timeline-row.selected { outline: 1px dashed var(--secondary); outline-offset: -1px; }
.tabs-list { margin: 14px 14px 0px; padding: 4px; gap: 3px; border: 0px; border-radius: 16px; background: var(--surface-subtle); }
.tabs-trigger { flex: 1 1 0%; padding: 7px 4px; border-radius: 12px; }
.tabs-trigger[data-state="active"] { background: var(--surface); box-shadow: var(--glass-shadow); color: var(--text); }
.tabs-trigger[data-state="active"]::after { display: none; }
.evidence-list > button { margin-top: 7px; border: 1px solid transparent; border-radius: 16px; padding: 12px 9px; }
.evidence-list > button.selected { background: var(--surface); border-color: var(--glass-rim); box-shadow: var(--glass-shadow); }
.inline-citations button > span, .citation-square { border-radius: 7px; }
.inline-citations button[aria-pressed="true"] > span, .evidence-list > button.selected .citation-square { background: var(--selection-bg); color: var(--selection-text); border: 1px solid var(--selection-border); box-shadow: inset 0 1px 0 var(--glass-highlight); font-weight: 600; }
.select-content, .dialog-content, .inspector-drawer, .mobile-progress { background: var(--glass-popup); border-color: var(--glass-rim); backdrop-filter: blur(var(--glass-blur)) saturate(1.2); box-shadow: var(--glass-shadow),
    0 16px 50px #102a4326; }
.select-content { border-radius: 17px; }
.dialog-content { border-radius: 24px; }
.inspector-drawer { border-radius: 24px 0px 0px 24px; }
.tooltip { color: var(--bg); }
.workspace-footer { padding: 14px 2px 18px; }
.workspace-footer .brand-mark { border: 0px; box-shadow: none; background: transparent; }
.workspace-footer .brand-mark svg { width: 14px; height: 14px; }
@media (min-width: 1181px) and (max-height: 1000px) {
  .workbench { height: calc(-330px + 100dvh); min-height: 570px; }
  .pane-heading { height: 48px; }
}
@media (min-width: 1181px) and (max-height: 840px) {
  .app-shell { margin-block: 12px; width: calc(100% - 32px); border-radius: 24px; }
  .topbar { height: 52px; border-radius: 24px 24px 0px 0px; }
  .rail { height: calc(-90px + 100dvh); top: 12px; }
  main { padding: 12px 20px 0px; }
  .page-heading { margin-bottom: 12px; }
  .page-heading h1 { font-size: 24px; }
  .page-heading > div > .section-kicker { display: none; }
  .page-heading p { margin-top: 0px; }
  .workbench { height: calc(-190px + 100dvh); min-height: 570px; }
  .pane-heading { height: 40px; }
  .workspace-footer { padding-block: 6px; }
  .graph-canvas { height: 288px; }
  .graph-toolbar { display: none; }
  .timeline { min-height: 140px; }
}
@media (max-width: 1180px) {
  .app-shell { width: calc(100% - 32px); margin-block: 16px; }
  .rail { height: calc(-120px + 100dvh); }
  main { padding: 22px 18px 0px; }
  .page-heading h1 { font-size: 26px; }
  .inspector-rail { box-shadow: none; }
  .inspector-rail .inspector-toggle { border-radius: 18px 0px 0px 18px; }
}
@media (max-width: 760px) {
  .app-shell { grid-template-columns: 44px minmax(0px, 1fr); width: calc(100% - 16px); margin: 8px auto; border-radius: 22px; }
  .topbar { height: 62px; padding: 0px 14px; border-radius: 22px 22px 0px 0px; }
  .brand-home { font-size: 18px; gap: 8px; }
  .wordmark-divider, .breadcrumb, .topbar-note { display: none; }
  .rail { width: 44px; top: 8px; height: calc(-86px + 100dvh); }
  .rail .button-icon { width: 34px; height: 38px; border-radius: 12px; }
  main { padding: 22px 10px 0px; }
  .page-heading { gap: 16px; margin-bottom: 18px; }
  .page-heading h1 { font-size: 25px; }
  .page-heading p { font-size: 11px; }
  .mode-control { gap: 8px; }
  .connection-note { font-size: 10px; }
  .workbench { gap: 16px; }
  .conversation-pane { margin: 0px; }
  .conversation-pane, .execution-pane { border-radius: 20px; }
  .conversation-scroll { padding: 20px 16px; }
  .welcome h2 { font-size: 20px; }
  .composer { padding: 12px; }
  .input-wrap { padding: 11px; border-radius: 16px; }
  .graph-toolbar { padding-inline: 12px; }
  .graph-view-label, .graph-key { font-size: 10px; }
  .evidence-dialog { border-radius: 24px 24px 0px 0px; }
}
@supports not (backdrop-filter: blur(1px)) {
  :root { --glass-panel: #e9f3fa; --glass-conversation: #f4f9fd; --glass-popup: #f4f9fd; }
  :root[data-theme="dark"] { --glass-panel: #294257; --glass-conversation: #233b50; --glass-popup: #233b50; }
}
@media (prefers-reduced-transparency: reduce) {
  :root { --glass-panel: #e9f3fa; --glass-conversation: #f4f9fd; --glass-popup: #f4f9fd; --glass-blur: 0px; }
  :root[data-theme="dark"] { --glass-panel: #294257; --glass-conversation: #233b50; --glass-popup: #233b50; }
}
